#include "ksPanelMasksTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
int main(){using T=ks::PanelMasksTask;using S=T::Stage;using R=T::Read;using W=T::Write;unsigned cases=0;for(unsigned mode=0;mode<3;++mode)for(unsigned pattern=0;pattern<16;++pattern)for(unsigned previous=0;previous<256;++previous)for(unsigned toggle:{0u,1u,85u,255u}){T t;unsigned used=0,reads=0;uint8_t port=0,mask=mode==1?uint8_t(0xff^(pattern<<4)):uint8_t(pattern),other=0xa5,output=mode==1?uint8_t((toggle&mask)^other):uint8_t((toggle^mask)&other);std::vector<std::pair<W,unsigned>>writes;while(t.stage()!=S::Complete){auto cost=t.nextClocks();if(t.advanceBefore(cost-1,[](R)->unsigned{throw std::runtime_error("early read");},[](W,uint8_t){throw std::runtime_error("early write");}))throw std::runtime_error("budget");used+=t.advanceBefore(cost,[&](R r)->unsigned{switch(r){case R::PendingMask:return mode==1?1:0;case R::PendingInvert:return mode==2?1:0;case R::Decay:++reads;return(pattern>>t.index())&1;case R::Previous:return previous;case R::Toggle:return toggle;case R::Other:return other;case R::Port:return port;}return 0;},[&](W w,uint8_t v){writes.emplace_back(w,v);if(w==W::Port||w==W::Strobe)port=v;});}std::vector<std::pair<W,unsigned>>expected;if(mode){expected.emplace_back(W::Pending,0);if(previous!=mask){expected.emplace_back(W::Mask,mask);expected.emplace_back(W::Data,output);expected.emplace_back(W::Port,0x34);expected.emplace_back(W::Strobe,0x14);expected.emplace_back(W::Strobe,0x34);}}if(writes!=expected||reads!=(mode?4:0)||t.mask()!=(mode?mask:0)||t.index()!=(mode?4:0)||t.remaining())throw std::runtime_error("mask service algorithm/order/lifecycle");unsigned population=0;for(unsigned i=0;i<4;++i)population+=(pattern>>i)&1;unsigned expectedClocks=mode?(previous==mask?190:308)+3*population:47;if(used!=expectedClocks)throw std::runtime_error("mask clocks");++cases;}std::cout<<"PASS: "<<cases<<" pure panel-masks properties\n";}
